// The bundled Lucide icon subset (public/renderer/icons.js, generated by scripts/build-icons.ts).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { ICONS, ICON_ALIASES, ICON_NAMES, iconData } from "../public/renderer/icons.js";

const TAGS = new Set(["path", "circle", "rect", "line", "polyline", "polygon", "ellipse"]);
const ATTRS = new Set(["d", "cx", "cy", "r", "rx", "ry", "x", "y", "x1", "y1", "x2", "y2", "width", "height", "points"]);

test("every curated name and alias resolves", () => {
  assert.ok(ICON_NAMES.length >= 90);
  for (const name of ICON_NAMES) assert.ok(iconData(name), name);
  for (const [alias, target] of Object.entries(ICON_ALIASES)) {
    assert.ok(ICON_NAMES.includes(target), `${alias} -> ${target}`);
    assert.equal(iconData(alias), ICONS[target], alias);
  }
});

test("names are matched case-insensitively and tolerate spaces and underscores", () => {
  assert.equal(iconData("Home"), ICONS["home"]);
  assert.equal(iconData("BAR_CHART 3".replace(" ", "-")), ICONS["bar-chart-3"]);
  assert.equal(iconData("Money Bag"), ICONS["wallet"]);
  assert.equal(iconData("  CHART "), ICONS["bar-chart-3"]);
});

test("unknown, empty and prototype names resolve to null", () => {
  for (const bad of ["nope", "", "__proto__", "constructor", "toString", undefined, null]) assert.equal(iconData(bad as any), null, String(bad));
});

test("stored elements are geometry only", () => {
  for (const [name, els] of Object.entries(ICONS)) {
    assert.ok(els.length > 0, name);
    for (const [tag, attrs] of els) {
      assert.ok(TAGS.has(tag), `${name}: <${tag}>`);
      for (const key of Object.keys(attrs)) {
        assert.ok(ATTRS.has(key), `${name}: ${key}`);
        assert.ok(!/^on/i.test(key) && !/href/i.test(key), `${name}: ${key}`);
      }
    }
  }
});

test("icons.js is import-free, sorted, and carries the Lucide ISC notice", () => {
  const src = readFileSync(new URL("../public/renderer/icons.js", import.meta.url), "utf8");
  assert.match(src, /ISC/);
  assert.match(src, /Lucide/);
  assert.match(src, /do not edit/);
  assert.doesNotMatch(src, /^\s*import\s/m);
  assert.deepEqual(ICON_NAMES, [...ICON_NAMES].sort());
});
